 "content": "from collections import deque


def transform(grid):
    """Reverse the color order of nested rectangular layers in each object."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 0 or seen[sr][sc]:
                continue
            q = deque([(sr, sc)])
            seen[sr][sc] = True
            cells = []
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr, nc))

            boxes = {}
            for r, c in cells:
                color = grid[r][c]
                if color not in boxes:
                    boxes[color] = [r, r, c, c]
                else:
                    b = boxes[color]
                    b[0] = min(b[0], r); b[1] = max(b[1], r)
                    b[2] = min(b[2], c); b[3] = max(b[3], c)
            layers = sorted(boxes, key=lambda color: (
                (boxes[color][1] - boxes[color][0] + 1) * (boxes[color][3] - boxes[color][2] + 1),
                boxes[color][1] - boxes[color][0] + boxes[color][3] - boxes[color][2]
            ), reverse=True)
            mapping = dict(zip(layers, reversed(layers)))
            for r, c in cells:
                out[r][c] = mapping[grid[r][c]]
    return out


